"""Regenerate native/mod/winhttp_forwards.inc from the local System32 winhttp.dll.

Uses the GLOBALROOT absolute-path forwarder technique (as in mrexodia's
perfect-dll-proxy) so the proxy never resolves back to itself.
"""
import os
import pefile

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
pe = pefile.PE(os.path.join(os.environ["SystemRoot"], "System32", "winhttp.dll"))
BS = "\\"
target = BS * 4 + "." + BS * 2 + "GLOBALROOT" + BS * 2 + "SystemRoot" + BS * 2 + "System32" + BS * 2 + "winhttp.dll"
lines = [
    "// Generated by tools/gen_winhttp_proxy.py from System32 winhttp.dll.",
    "// ds.exe statically imports winhttp.dll, which is not a KnownDLL, so a copy in",
    "// the game folder is loaded first. Every export is forwarded to the real",
    "// System32 copy through a GLOBALROOT path (no drive letter assumption).",
    "#pragma once",
]
for e in pe.DIRECTORY_ENTRY_EXPORT.symbols:
    n = e.name.decode()
    lines.append(f'#pragma comment(linker, "/export:{n}={target}.{n},@{e.ordinal}")')
out = os.path.join(root, "native", "mod", "winhttp_forwards.inc")
with open(out, "w", newline="\n") as f:
    f.write("\n".join(lines) + "\n")
print(f"wrote {len(lines) - 5} forwarders to {out}")
